    public UUID transferId(){return transfer;}public UUID catalogue(){return catalogue;}public UUID groupId(){return group;}public ApplyPosition catalogueCut(){return catalogueCut;}public ApplyPosition imageCut(){return imageCut;}public RangeDirectory directory(){return directory;}public DistributedSchema schema(){return schema;}public ReplicaDescriptor receiver(){return receiver;}public ReplicaDescriptor sourceOwner(){return source;}public long configurationTerm(){return configurationTerm;}public long configurationIndex(){return configurationIndex;}public byte[] sourceConfiguration(){return configuration.clone();}public byte[] imageHash(){return imageHash.clone();}public NativeTopologyImageOrigin origin(){return origin;}public Map<UUID,String> physicalNames(){return names;}public Set<UUID> mergeColumns(){return merges;}public Map<String,byte[]> sourceSchemaRows(){return NativeTopologyLearnerSchema.copy(sourceRows);}public Map<String,byte[]> localSchemaRows(){return NativeTopologyLearnerSchema.copy(localRows);}
