    private byte[] encodeFields(){try{var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeInt(0x43525247);uuid(out,transfer);uuid(out,catalogue);uuid(out,group);cut(out,catalogueCut);cut(out,imageCut);blob(out,RangeDirectoryCodec.encode(directory));blob(out,DistributedSchemaCodec.encode(schema));owner(out,receiver);owner(out,source);out.write(imageHash);out.writeLong(configurationTerm);out.writeLong(configurationIndex);blob(out,configuration);blob(out,origin==null?new byte[0]:origin.encode());out.writeInt(names.size());for(var id:names.keySet().stream().sorted(RangeDirectoryCodec.UUID_ORDER).toList()){uuid(out,id);out.writeUTF(names.get(id));out.writeBoolean(merges.contains(id));}out.writeInt(sourceRows.size());for(var key:sourceRows.keySet().stream().sorted().toList()){out.writeUTF(key);blob(out,sourceRows.get(key));}out.flush();return bytes.toByteArray();}catch(IOException impossible){throw new AssertionError(impossible);}}
